// Implementation using the member function swap
std::fstream fstream1("file1.txt", std::ios::in);
std::fstream fstream2("file2.txt", std::ios::out);

if (fstream1.is_open() && fstream2.is_open()) {
    // Efficiently exchanges std::basic_filebuf pointers
    // and stream state flags (good/fail/eof)
    fstream1.swap(fstream2);
}

// Alternatively, using the standard algorithm (ADL finds fstream::swap)
using std::swap;
swap(fstream1, fstream2);
